IPAddress gateway(192, 168, 1, 1);
IPAddress subnet(255, 255, 255, 0);
EthernetServer server(80);                           // port HTTP

// -------------------------------------------------
// Identifiants d'authentification (en clair)
// -------------------------------------------------
const char USER[] = "admin";
const char PASS[] = "1234";

// -------------------------------------------------
// Fonction d'encodage Base64 (pour l'en-tête Authorization)
// -------------------------------------------------
String base64Encode(const char *input) {
  const char *b64chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  String result;
  int i = 0, len = strlen(input);
  while (i < len) {
    uint32_t octet_a = i < len ? (uint8_t)input[i++] : 0;
    uint32_t octet_b = i < len ? (uint8_t)input[i++] : 0;
    uint32_t octet_c = i < len ? (uint8_t)input[i++] : 0;

    uint32_t triple = (octet_a << 0x10) + (octet_b << 0x08) + octet_c;

    result += b64chars[(triple >> 3 * 6) & 0x3F];
    result += b64chars[(triple >> 2 * 6) & 0x3F];
    result += b64chars[(triple >> 1 * 6) & 0x3F];
    result += b64chars[(triple >> 0 * 6) & 0x3F];
  }

  // Gestion du remplissage '='
  int mod = len % 3;
  if (mod) {
    result[result.length() - 1] = '=';
    if (mod == 1) result[result.length() - 2] = '=';
  }
  return result;
}

